function validateNumber(x) {
  if (typeof x !== 'number' || !Number.isFinite(x)) throw Error('x');
}

function resolveOperation(kind) {
  if (kind === 'bonus') return { multiplier: 2, offset: 5 };
  if (typeof kind !== 'string' || !/^type(?:[0-9]|[12][0-9])$/.test(kind)) {
    throw Error('kind');
  }
  return { multiplier: Number(kind.slice(4)) + 1, offset: 0 };
}

function run({ kind, x }) {
  validateNumber(x);
  const { multiplier, offset } = resolveOperation(kind);
  const result = x * multiplier;
  return offset === 0 ? result : result + offset;
}

module.exports = { run };
